            67,
            &[
                simple_block(2, 0, false, Lacing::None, &[v[2].clone()]),
                simple_block(4, -7, true, Lacing::None, &[a[2].clone()]),
                simple_block(2, 33, false, Lacing::None, &[v[3].clone()]),
            ],
        ),
    ];
    (file("webm", &body, false), v, a)
}

