// Codec spike #377, question 5: does macOS encode Opus itself?
// (1) AVAudioConverter PCM → Opus packets, at a bitrate asked for (what a WebM writer would mux);
// (2) AVAssetWriter with kAudioFormatOpus into .mp4 and .mov.
import AVFoundation
let pcmFmt = AVAudioFormat(commonFormat: .pcmFormatFloat32, sampleRate: 48000, channels: 2, interleaved: true)!
var asbd = AudioStreamBasicDescription(mSampleRate: 48000, mFormatID: kAudioFormatOpus, mFormatFlags: 0, mBytesPerPacket: 0, mFramesPerPacket: 960, mBytesPerFrame: 0, mChannelsPerFrame: 2, mBitsPerChannel: 0, mReserved: 0)
let opusFmt = AVAudioFormat(streamDescription: &asbd)!
let conv = AVAudioConverter(from: pcmFmt, to: opusFmt)!
for rate in [64000, 128000, 192000] {
    conv.reset()
    conv.bitRate = rate
    let secs = 5.0, total = AVAudioFrameCount(48000 * secs)
    let src = AVAudioPCMBuffer(pcmFormat: pcmFmt, frameCapacity: total)!; src.frameLength = total
    let p = src.floatChannelData![0]
    var seed: UInt32 = 1
    for i in 0..<Int(total) { seed = seed &* 1664525 &+ 1013904223; let noise = Float(Int32(bitPattern: seed)) / Float(Int32.max) * 0.05
        let v = 0.3 * sin(2 * .pi * 440 * Float(i) / 48000) + noise; p[2*i] = v; p[2*i+1] = v }
    var fed = false, bytes = 0, packets = 0
    while true {
        let out = AVAudioCompressedBuffer(format: opusFmt, packetCapacity: 64, maximumPacketSize: conv.maximumOutputPacketSize)
        var err: NSError?
        let st = conv.convert(to: out, error: &err) { _, status in
            if fed { status.pointee = .endOfStream; return nil }
            fed = true; status.pointee = .haveData; return src }
        packets += Int(out.packetCount); bytes += Int(out.byteLength)
        if st == .endOfStream || st == .error || out.packetCount == 0 { if st == .error { print("error \(String(describing: err))") }; break }
    }
    let cookie = conv.magicCookie
    print("AVAudioConverter Opus asked \(rate) b/s: actual bitRate prop \(conv.bitRate), \(packets) packets, \(Int(Double(bytes) * 8 / secs)) b/s measured, cookie \(cookie?.count ?? 0) bytes \(cookie.map { $0.prefix(19).map { String(format: "%02x", $0) }.joined() } ?? "-"), primeInfo leading \(conv.primeInfo.leadingFrames) trailing \(conv.primeInfo.trailingFrames)")
}
for (ext, type) in [("mp4", AVFileType.mp4), ("mov", AVFileType.mov), ("m4a", AVFileType.m4a)] {
    let url = URL(fileURLWithPath: "/tmp/codec-spike-opus.\(ext)"); try? FileManager.default.removeItem(at: url)
    let w = try AVAssetWriter(outputURL: url, fileType: type)
    let i = AVAssetWriterInput(mediaType: .audio, outputSettings: [AVFormatIDKey: kAudioFormatOpus, AVSampleRateKey: 48000, AVNumberOfChannelsKey: 2, AVEncoderBitRateKey: 128000])
    print("AVAssetWriter Opus into .\(ext): canAdd \(w.canAdd(i))")
}

